    '6' : {
      $release_major = '6u45'
      $release_minor = 'b06'
      $install_path = "${java_se}1.6.0_45"
    }
    '7' : {
      $release_major = '7u80'
      $release_minor = 'b15'
      $install_path = "${java_se}1.7.0_80"
    }
    '8' : {
      $release_major = '8u51'
      $release_minor = 'b16'
      $install_path = "${java_se}1.8.0_51"
    }
